import { lookupModule } from '@valenced/modules/finders'
import { withProps } from '@valenced/modules/finders/filters'
import { IMAGE_APP_ID, IMAGE_TYPES, TAG } from './constants'
import { assetCache, setImageStatus } from './state'
import { fill } from './variables'
import type { AssetUtils, Http } from './types'

/** Links already looked at, so a page is only fetched once. */
const linkCache = new Map<string, string>()

/** Finds a module by the functions it has, described by the type the caller gives. */
const findByProps = <T>(...props: string[]): T | undefined =>
	lookupModule(
		(withProps as (...names: string[]) => ReturnType<typeof withProps>)(
			...props,
		),
	)[0] as unknown as T | undefined

/** A link found in a page, made absolute against the page's address. */
function absoluteUrl(found: string, base: string): string | undefined {
	try {
		return new URL(found.replace(/&amp;/g, '&'), base).href
	} catch {
		return undefined
	}
}

/**
 * Turns any link you could post in chat into a direct image link: image links stay as they are, Imgur page links become
 * the image, and other pages give the picture Discord would embed (`og:image` and its relatives, a `link rel=image_src`,
 * or for postimg.cc the direct link in the page). A page that cannot be read is left as the link it was.
 */
export async function findImageUrl(link: string): Promise<string> {
	const known = linkCache.get(link)
	if (known !== undefined) return known
	let result = link
	try {
		const imgur =
			/^https?:\/\/(?:www\.|m\.)?imgur\.com\/(?!a\/|gallery\/|t\/)(\w{5,8})\/?$/i.exec(
				link,
			)
		if (imgur) {
			result = `https://i.imgur.com/${imgur[1]}.png`
		} else if (!IMAGE_TYPES.test(link)) {
			const res = await fetch(link, {
				headers: {
					'User-Agent':
						'Mozilla/5.0 (compatible; Discordbot/2.0; +https://discordapp.com)',
					Accept: 'text/html,image/*',
				},
			})
			const type = res.headers?.get?.('content-type') || ''
			if (res.ok && !/^image\//i.test(type)) {
				const html = (await res.text()).slice(0, 400000)
				const tags = html.match(/<meta[^>]+>|<link[^>]+>/gi) || []
				const wanted = [
					'og:image:secure_url',
					'og:image:url',
					'og:image',
					'twitter:image',
					'twitter:image:src',
				]
				let found: string | undefined
				for (let w = 0; w < wanted.length && !found; w++) {
					for (let t = 0; t < tags.length && !found; t++) {
						const tag = tags[t]
						const name = /(?:property|name)=["']([^"']+)["']/i.exec(tag)
						const content = /content=["']([^"']+)["']/i.exec(tag)
						if (name && content && name[1].toLowerCase() === wanted[w])
							found = content[1]
					}
				}
				if (!found) {
					const rel = tags.filter(x => /rel=["']image_src["']/i.test(x))[0]
					const href = rel && /href=["']([^"']+)["']/i.exec(rel)
					if (href) found = href[1]
				}
				if (!found) {
					// Pages like postimg.cc show the direct link in the page even without preview tags.
					const direct =
						/https:\/\/i\.postimg\.cc\/[^"'\s<>]+?\.(?:png|jpe?g|gif|webp)/i.exec(
							html,
						)
					if (direct) found = direct[0]
				}
				const abs = found && absoluteUrl(found, link)
				if (abs) result = abs
			}
		}
	} catch {
		// The link is used as it was.
	}
	linkCache.set(link, result)
	return result
}

/** Links that are signed or expire, where adding anything to the link could make it stop working. */
const SIGNED_LINK =
	/[?&](?:ex|is|hm|sig|signature|token|expires|x-amz-[a-z-]+|x-goog-[a-z-]+)=/i

/** Discord's own storage links are signed, and Discord already gives each upload its own link. */
const DISCORD_STORAGE = /^https?:\/\/(?:cdn|media)\.discordapp\.(?:com|net)\//i

/** How long the version of a link is kept before the picture is looked at again, so a refresh every few seconds costs nothing. */
const VERSION_TTL_MS = 10 * 60_000

/** The biggest picture that is looked at (bytes). A bigger one is used as it is. */
const VERSION_MAX_BYTES = 4 * 1024 * 1024

/** The name of the version added to a link. */
const VERSION_PARAM = 'ev'

/** Links already looked at, with the link to send and when it was made. */
const versionCache = new Map<string, { link: string; at: number }>()

/** A short fingerprint of some bytes (FNV-1a, 32 bits) as 8 hex digits. */
export function fingerprint(bytes: Uint8Array): string {
	let hash = 0x811c9dc5
	for (let i = 0; i < bytes.length; i++) {
		hash ^= bytes[i] as number
		hash = Math.imul(hash, 0x01000193)
	}
	return (hash >>> 0).toString(16).padStart(8, '0')
}

/**
 * Makes a link change when the picture behind it changes.
 *
 * Discord keeps a copy of every linked image, by the exact link, and shows that copy for as long as it likes: a picture that
 * changes behind the same link (a profile picture that is updated, a "now playing" image) does not change in the presence.
 * The picture is fetched once, a fingerprint of it is added to the link (`?ev=1a2b3c4d`), and Discord is given that link. A new
 * picture is a new link, so Discord fetches it again; the same picture is the same link, so nothing is fetched twice. Signed
 * links are left as they are, and so is any link that cannot be fetched.
 *
 * @param link A direct image link.
 * @returns The link to send.
 */
export async function versionedLink(link: string): Promise<string> {
	if (SIGNED_LINK.test(link) || DISCORD_STORAGE.test(link)) return link
	const known = versionCache.get(link)
	if (known && Date.now() - known.at < VERSION_TTL_MS) return known.link
	let result = link
	try {
		const res = await fetch(link, { headers: { Accept: 'image/*' } })
		if (res.ok) {
			const bytes = new Uint8Array(await res.arrayBuffer())
			if (bytes.length > 0 && bytes.length <= VERSION_MAX_BYTES) {
				const cut = link.indexOf('#')
				const base = cut >= 0 ? link.slice(0, cut) : link
				const tail = cut >= 0 ? link.slice(cut) : ''
				result = `${base}${base.includes('?') ? '&' : '?'}${VERSION_PARAM}=${fingerprint(bytes)}${tail}`
			}
		}
	} catch {
		// The link is sent as it is.
	}
	versionCache.set(link, { link: result, at: Date.now() })
	return result
}

/**
 * Asks Discord to host an image link for use in a presence, under the given application.
 *
 * Discord's own connection is used when it can be found, and otherwise a plain request with the account token.
 *
 * @param app The application the presence is sent for, or `0`.
 * @param url The image link.
 * @returns An `mp:` asset id.
 */
async function externalAssetFor(app: string, url: string): Promise<string> {
	const path = `/applications/${app}/external-assets`
	const body = { urls: [url] }
	let list: Array<{ external_asset_path?: string }> | undefined
	const http =
		findByProps<Http>('HTTPResponseError', 'get') ||
		findByProps<Http>('get', 'post', 'patch')
	if (http && typeof http.post === 'function') {
		try {
			const answer = await http.post({ url: path, body })
			list = answer?.body as typeof list
		} catch (error) {
			// A real answer from Discord (an error with a status or body) is passed on; anything else tries the plain request.
			const e = error as { status?: unknown; body?: unknown } | undefined
			if (e && (e.status != null || e.body != null)) throw error
		}
	}
	if (!list) {
		const auth = findByProps<{ getToken?: () => string | undefined }>(
			'getToken',
		)
		const token = auth?.getToken?.()
		if (!token) throw new Error('Could not find a way to reach Discord')
		const res = await fetch(`https://discord.com/api/v9${path}`, {
			method: 'POST',
			headers: { Authorization: token, 'Content-Type': 'application/json' },
			body: JSON.stringify(body),
		})
		if (!res.ok) throw new Error(`Discord said no (${res.status})`)
		list = await res.json()
	}
	let link = list?.[0]?.external_asset_path
	if (!link) throw new Error('Discord returned no image for this link')
	if (/^https:\/\/media\.discordapp\.net/.test(link))
		link = link.split('/').slice(3).join('/')
	return `mp:${link}`
}

/**
 * Asks Discord to host an image link, under the application the presence is sent for when there is one (this is what
 * Discord's own asset code does), and under application `0` when that is not possible.
 *
 * @param url The image link.
 * @param appId The Application id of the profile, or nothing.
 * @returns An `mp:` asset id.
 */
async function externalAsset(url: string, appId?: string): Promise<string> {
	const own = appId && /^\d{5,}$/.test(appId.trim()) ? appId.trim() : undefined
	if (own) {
		try {
			return await externalAssetFor(own, url)
		} catch (error) {
			console.warn(
				`${TAG} could not host the image under application ${own}:`,
				errorText(error),
			)
		}
	}
	return externalAssetFor('0', url)
}

/** The text of an error from Discord's connection (its message, or the whole thing). */
const errorText = (error: unknown): string => {
	const e = error as
		| { body?: { message?: unknown }; message?: unknown }
		| undefined
	return String((e && ((e.body && e.body.message) || e.message)) || error)
}

/**
 * Turns an image link or asset key into a Discord asset id, and notes how it went for the preview.
 *
 * - An `mp:` id passes through unchanged.
 * - A link is first turned into a direct image link, then Discord's own asset code is tried, then Discord's web API.
 * - An asset key is tried with your Application id first, then the fallback one, then the application's public asset list.
 *
 * @param appId The Application id of the profile (`0` or empty for none).
 * @param value The image field as typed; variables are filled in.
 * @param slot `large` or `small`, for the status shown in the preview.
 * @returns The asset id, or nothing if the field is empty or the image could not be found (the preview says why).
 */
export async function resolveImage(
	appId: string,
	value: unknown,
	slot: string,
): Promise<string | undefined> {
	const filled = fill(value)
	if (typeof filled !== 'string' || !filled.trim()) {
		setImageStatus(slot, undefined)
		return undefined
	}
	let v: string = filled.trim()
	if (/^mp:/i.test(v)) return v
	const utils =
		findByProps<AssetUtils>('fetchAssetIds') ||
		findByProps<AssetUtils>('getAssetIds')
	const isLink = /^https?:\/\//i.test(v)
	if (isLink) v = await versionedLink(await findImageUrl(v))
	const wanted = v

	/** Asks Discord's web API to host the link. */
	async function viaDiscordApi(): Promise<string | undefined> {
		const key = `link|${wanted}`
		const cached = assetCache.get(key)
		if (cached !== undefined) {
			setImageStatus(slot, 'ok')
			return cached
		}
		try {
			const id = await externalAsset(wanted, appId)
			assetCache.set(key, id)
			setImageStatus(slot, 'ok')
			return id
		} catch (error) {
			setImageStatus(slot, errorText(error))
			return undefined
		}
	}

	/** Looks an asset key up in the application's public asset list. */
	async function viaAssetList(): Promise<string | undefined> {
		const apps = appId && appId !== '0' ? [appId, IMAGE_APP_ID] : [IMAGE_APP_ID]
		for (const app of apps) {
			const key = `${app}|${wanted}`
			const cached = assetCache.get(key)
			if (cached !== undefined) {
				setImageStatus(slot, 'ok')
				return cached
			}
			try {
				const res = await fetch(
					`https://discord.com/api/v9/oauth2/applications/${app}/assets`,
				)
				if (!res.ok) continue
				const assets = (await res.json()) as Array<{
					name?: string
					id?: string
				}>
				const hit = Array.isArray(assets)
					? assets.filter(a => a && (a.name === wanted || a.id === wanted))[0]
					: undefined
				if (hit?.id) {
					assetCache.set(key, hit.id)
					setImageStatus(slot, 'ok')
					return hit.id
				}
			} catch {
				// Try the next application.
			}
		}
		setImageStatus(
			slot,
			`No image called "${wanted}" was found for this Application ID`,
		)
		return undefined
	}

	if (!utils) return isLink ? viaDiscordApi() : viaAssetList()

	const candidates =
		appId && appId !== '0' ? [appId, IMAGE_APP_ID] : [IMAGE_APP_ID]
	let error: string | undefined
	for (const app of candidates) {
		const key = `${app}|${wanted}`
		const cached = assetCache.get(key)
		if (cached !== undefined) {
			setImageStatus(slot, 'ok')
			return cached
		}
		try {
			let ids: string[] | undefined
			try {
				ids = utils.getAssetIds?.(app, [wanted])
			} catch {
				// Asked below instead.
			}
			// `getAssetIds` answers `[null]`, not `[]`, for an image it has not seen once the application's art assets are loaded
			// (they are as soon as any profile uses an asset key). That is no answer, so Discord is asked, under this application.
			if (!ids?.[0]) ids = await utils.fetchAssetIds?.(app, [wanted])
			const id = ids?.[0]
			if (id) {
				assetCache.set(key, id)
				setImageStatus(slot, 'ok')
				return id
			}
			error = 'Discord returned no image for this link'
		} catch (e) {
			error = errorText(e)
			console.warn(`${TAG} could not resolve image:`, error)
		}
	}
	if (isLink) return viaDiscordApi()
	if (appId && appId !== '0') return viaAssetList()
	setImageStatus(slot, error || 'Could not load this image')
	return undefined
}

/**
 * Turns the link of a cover into an asset id Discord can show. A SoundCloud cover is asked for in its large size.
 * The same image is only hosted once.
 *
 * @returns The asset id, or nothing if there is no link or Discord would not host it (this is logged).
 */
export async function artworkAsset(url: string): Promise<string | undefined> {
	if (!url) return undefined
	const big = url.replace('-large.', '-t500x500.')
	const key = `link|${big}`
	const cached = assetCache.get(key)
	if (cached !== undefined) return cached
	try {
		const id = await externalAsset(big)
		assetCache.set(key, id)
		return id
	} catch (error) {
		console.warn(`${TAG} artwork not sent:`, errorText(error))
		return undefined
	}
}

index.ts:
/**
 * Rich Presence.
 *
 * Shows up to three presences at once on your Discord profile, each one a profile you set up, and the SoundCloud track you
 * are listening to. Each profile that is switched on is sent to Discord as its own local activity (`LOCAL_ACTIVITY_UPDATE`),
 * under its own made-up socket and process, as a game would report it. Discord's local activity store keeps one activity for
 * each socket, so each shows on your profile. Discord's app keeps only one "Playing" and merges activities with the same
 * application id, so each profile has its own Application ID (one is made up when you leave it empty).
 *
 * The SoundCloud profile is a special kind: it has no fields of its own, its settings are the SoundCloud ones. Discord cannot
 * see what another app plays, so the track comes from a link you paste or copy, or from Last.fm "now playing" filled in by a
 * scrobbler app such as Pano Scrobbler.
 *
 * Other plugins and profiles can work with it:
 * - `globalThis.eskimoRichPresence.apply()` asks for the presences to be sent again,
 * - `globalThis.eskimoVars` supplies variables (the SoundCloud track is `{sc_title}` and friends),
 * - `globalThis.eskimoTimestamps` gives the start and end of the timer when a profile's timer is "From the SoundCloud track".
 *
 * How it is put together:
 * - `activity.ts` builds the activity of one profile with its timer and sends it, `images.ts` turns image links and keys into
 *   asset ids,
 * - `timers.ts` has the time rules (dates, repeats, daily ranges, schedules) without any Discord code,
 * - `apply.ts` sends every profile that is shown (one after another), takes away the ones that are not, refreshes, and watches
 *   the clock for timers that change by themselves,
 * - `profiles.ts` has the profile shape, defaults, the limit and the plan of which profiles are shown,
 * - `state.ts` keeps what each profile needs (its socket, its process and its timers), `variables.ts` fills in `{time}` and the
 *   rest,
 * - the SoundCloud part: `soundcloud.ts` (what is shown and the actions), `present.ts` (builds and sends its presence within
 *   Discord's limits), `lastfm.ts` (follows Last.fm), `lookup.ts` (reads a pasted link), `scstate.ts`, `format.ts`,
 * - `constants.ts` and `types.ts` hold fixed values and types,
 * - `Settings.tsx` is the settings screen (`Preview.tsx` the live preview, `Field.tsx` a text box that saves when typing
 *   pauses).
 */

import { onFluxEventDispatched } from '@valenced/discord/flux'
import { AppState } from 'react-native'
import {
	applyAll,
	clearAll,
	ensureWatcher,
	restartRefresh,
	scheduleApply,
} from './apply'
import {
	CLIPBOARD_AT_START_MS,
	CLIPBOARD_ON_RETURN_MS,
	RECONNECT_DELAY_MS,
	SPOTIFY_DELAY_MS,
} from './constants'
import { poll } from './lastfm'
import { DEFAULT_SETTINGS } from './profiles'
import Settings from './Settings'
import { sc } from './scstate'
import { checkClipboard, refreshSoundCloud, syncSoundCloud } from './soundcloud'
import { forgetRuntimes, read, setStorage, state } from './state'
import { markAppStart } from './timers'
import type { RichPresenceSettings } from './types'

/** What other plugins can call. */
const richApi = { apply: () => scheduleApply(false) }

const shared = globalThis as unknown as { eskimoRichPresence?: typeof richApi }

export default plugin<{ jsonStorage: RichPresenceSettings }>({
	jsonStorage: { load: true, default: DEFAULT_SETTINGS },
	SettingsComponent: Settings,

	start({ cleanup, jsonStorage, plugin }) {
		setStorage(jsonStorage)
		markAppStart()
		shared.eskimoRichPresence = richApi
		state.active = true
		sc.auto = null

		cleanup(() => {
			state.active = false
			clearTimeout(state.applyTimer)
			clearInterval(state.refreshTimer)
			clearInterval(state.loopTimer)
			clearTimeout(sc.endTimer)
			clearInterval(sc.pollTimer)
			clearTimeout(sc.endPollTimer)
			clearTimeout(sc.missTimer)
			sc.missPending = false
			state.pending.clear()
			state.pendingAll = false
			try {
				clearAll()
			} catch {
				// Discord is already shutting down.
			}
			forgetRuntimes()
			if (shared.eskimoRichPresence === richApi)
				shared.eskimoRichPresence = undefined
		})

		// Wait for the saved settings, then start the watcher and the refresh timer and, if asked, send the presences.
		Promise.resolve(jsonStorage.cache || jsonStorage.get()).then(() => {
			if (!state.active) return
			ensureWatcher()
			restartRefresh()
			if (read().applyOnStart) applyAll(true)
			syncSoundCloud()
			if (read().soundcloud.clipboardOnOpen)
				setTimeout(() => checkClipboard(true), CLIPBOARD_AT_START_MS)
		})

		// Opening Discord again checks the clipboard (if you asked for that) and Last.fm.
		try {
			const sub = AppState.addEventListener('change', appState => {
				if (appState !== 'active') return
				const s = read().soundcloud
				if (s.clipboardOnOpen)
					setTimeout(() => checkClipboard(true), CLIPBOARD_ON_RETURN_MS)
				if (s.autoEnabled) poll()
			})
			cleanup(() => {
				try {
					sub.remove()
				} catch {
					// Already removed.
				}
			})
		} catch {
			// This phone does not report the app coming back.
		}

		// Discord drops local activities on reconnect, so every presence has to be sent again.
		cleanup(
			onFluxEventDispatched('CONNECTION_OPEN', payload => {
				sc.lastSentJson = ''
				setTimeout(() => applyAll(false), RECONNECT_DELAY_MS)
				return payload
			}),
		)

		// Spotify starting or stopping decides whether the SoundCloud presence steps aside.
		for (const name of ['SPOTIFY_PLAYER_STATE', 'SPOTIFY_PLAYER_PLAY']) {
			try {
				cleanup(
					onFluxEventDispatched(name, payload => {
						if (read().soundcloud.hideWithSpotify)
							setTimeout(() => refreshSoundCloud(), SPOTIFY_DELAY_MS)
						return payload
					}),
				)
			} catch {
				// This event is not available.
			}
		}
	},
})

lastfm.ts:
import { LASTFM_BLANK, MIN_POLL_SECONDS, TAG } from './constants'
import { searchLink } from './format'
import { soundCloudOn } from './profiles'
import { hooks, notifyListeners, sc, setStatus, tuning } from './scstate'
import { read, state } from './state'
import type { LastfmAnswer, NowPlaying, Track } from './types'

/** Gives up on a request that takes too long, so one stuck request cannot hold up every later check. */
function withTimeout<T>(promise: Promise<T>, message: string): Promise<T> {
	return new Promise<T>((resolve, reject) => {
		const timer = setTimeout(
			() => reject(new Error(message)),
			tuning.requestTimeout,
		)
		promise.then(
			value => {
				clearTimeout(timer)
				resolve(value)
			},
			error => {
				clearTimeout(timer)
				reject(error)
			},
		)
	})
}

/**
 * Calls a Last.fm method for the user's name and API key.
 *
 * @param method For example `user.getrecenttracks`.
 * @param params The method's own parameters.
 * @throws If the name or key is missing, Last.fm says no, or it does not answer in time.
 */
async function lastfm(
	method: string,
	params: Record<string, string>,
): Promise<LastfmAnswer> {
	const s = read().soundcloud
	const user = String(s.lfmUser || '').trim()
	const key = String(s.lfmKey || '').trim()
	if (!user || !key)
		throw new Error('Enter your Last.fm name and API key first')
	const qs = Object.keys(params)
		.map(k => `${k}=${encodeURIComponent(params[k])}`)
		.join('&')
	// The changing "_" value keeps a cached copy of an older answer from being served.
	const url = `https://ws.audioscrobbler.com/2.0/?method=${method}&api_key=${encodeURIComponent(key)}&format=json&${qs}&_=${Date.now()}`
	return withTimeout(
		(async () => {
			const res = await fetch(url)
			let data: LastfmAnswer | undefined
			try {
				data = await res.json()
			} catch {
				// Not JSON: the status below says what went wrong.
			}
			if (!res.ok || data?.error)
				throw new Error(
					data?.message
						? `Last.fm: ${data.message}`
						: `Last.fm said no (${res.status})`,
				)
			return data as LastfmAnswer
		})(),
		'Last.fm did not answer in time',
	)
}

/** A song or artist name made easy to compare: lower case, without bracketed parts, with spaces for punctuation. */
function normalize(s: unknown): string {
	return String(s == null ? '' : s)
		.toLowerCase()
		.replace(/\([^)]*\)|\[[^\]]*\]/g, ' ')
		.replace(/[\s\-_.,:;!?'"|/\\&+]+/g, ' ')
		.trim()
}

/**
 * Looks a song up in Apple Music's public search for its cover.
 * A result only counts when both the title and the artist match, so a wrong cover is never shown. Songs that exist only
 * on SoundCloud are usually not there.
 *
 * @returns The link to a 600 pixel cover, or an empty text.
 */
async function findCover(artist: string, title: string): Promise<string> {
	try {
		const res = await withTimeout(
			fetch(
				`https://itunes.apple.com/search?media=music&entity=song&limit=5&term=${encodeURIComponent(`${artist} ${title}`)}`,
			),
			'Apple Music did not answer in time',
		)
		if (!res.ok) return ''
		const data = (await res.json()) as {
			results?: Array<{
				trackName?: string
				artistName?: string
				artworkUrl100?: string
			}>
		}
		const wantTitle = normalize(title)
		const wantArtist = normalize(artist)
		if (!wantTitle || !wantArtist) return ''
		for (const item of data?.results || []) {
			const t = normalize(item.trackName)
			const a = normalize(item.artistName)
			const titleOk =
				t &&
				(t === wantTitle ||
					t.indexOf(wantTitle) === 0 ||
					wantTitle.indexOf(t) === 0)
			const artistOk =
				a && (a.indexOf(wantArtist) >= 0 || wantArtist.indexOf(a) >= 0)
			if (titleOk && artistOk && item.artworkUrl100)
				return String(item.artworkUrl100).replace('100x100bb', '600x600bb')
		}
	} catch {
		// No cover is found; the default cover is used.
	}
	return ''
}

/** The largest real picture of a list of Last.fm images. Last.fm's empty picture does not count. */
function pickImage(images: unknown): string {
	if (!Array.isArray(images)) return ''
	for (let i = images.length - 1; i >= 0; i--) {
		const url = images[i]?.['#text']
		if (url && url.indexOf(LASTFM_BLANK) < 0) return url
	}
	return ''
}

/**
 * The song Last.fm says you are playing right now.
 *
 * @returns The song, or nothing if Last.fm says nothing is playing.
 */
export async function fetchNowPlaying(): Promise<NowPlaying | null> {
	const data = await lastfm('user.getrecenttracks', {
		user: String(read().soundcloud.lfmUser).trim(),
		limit: '1',
	})
	const list = (data?.recenttracks as { track?: unknown } | undefined)?.track
	const t = (Array.isArray(list) ? list[0] : list) as
		| {
				'@attr'?: { nowplaying?: unknown }
				artist?: { '#text'?: string; name?: string }
				name?: string
				album?: { '#text'?: string }
				image?: unknown
		  }
		| undefined
	if (!t || !t['@attr'] || String(t['@attr'].nowplaying) !== 'true') return null
	const artist = t.artist?.['#text'] || t.artist?.name || ''
	const title = t.name || ''
	if (!title) return null
	return {
		artist,
		title,
		album: t.album?.['#text'] || '',
		artwork: pickImage(t.image),
	}
}

/** Fills in what takes extra requests (length, album, cover) and updates the status once if anything was found. */
async function enrich(track: Track): Promise<void> {
	try {
		const wantCover = !track.artwork && read().soundcloud.coverLookup
		const results = await Promise.all([
			lastfm('track.getinfo', {
				artist: track.artist,
				track: track.title,
				autocorrect: '1',
			}).then(
				v => v,
				() => null,
			),
			wantCover ? findCover(track.artist, track.title) : '',
		])
		if (!state.active || sc.auto !== track) return
		const found = results[0]?.track as
			| { duration?: unknown; album?: { title?: string; image?: unknown } }
			| undefined
		let changed = false
		const duration = Number(found?.duration) || 0
		if (duration && duration !== track.duration) {
			track.duration = duration
			changed = true
		}
		if (!track.album && found?.album?.title) {
			track.album = found.album.title
			changed = true
		}
		if (!track.artwork) {
			// The track's own album art is preferred, then the Apple Music result.
			const art =
				(found?.album && pickImage(found.album.image)) || results[1] || ''
			if (art) {
				track.artwork = art
				changed = true
			}
		}
		if (changed) await hooks.refresh()
	} catch (error) {
		console.warn(`${TAG} extra lookups failed:`, String(error))
	}
}

/**
 * Checks Last.fm once and keeps `sc.auto` in step with what is playing.
 *
 * A new song goes on the profile at once; its length and a better cover are looked up afterwards. The first time Last.fm
 * reports nothing, one more look is taken a few seconds later before the status is cleared, so the gap between two songs
 * does not make it flicker off.
 */
export async function poll(): Promise<void> {
	const settings = read()
	const s = settings.soundcloud
	if (
		sc.polling ||
		!state.active ||
		!soundCloudOn(settings) ||
		!s.autoEnabled ||
		!String(s.lfmUser).trim() ||
		!String(s.lfmKey).trim()
	)
		return
	sc.polling = true
	sc.lastPollAt = Date.now()
	try {
		const np = await fetchNowPlaying()
		if (!state.active) return
		if (!np) {
			if (sc.auto) {
				if (!sc.missPending) {
					sc.missPending = true
					clearTimeout(sc.missTimer)
					sc.missTimer = setTimeout(poll, tuning.recheckMs)
					return
				}
				sc.missPending = false
				sc.auto = null
				await hooks.refresh()
			}
			return
		}
		sc.missPending = false
		clearTimeout(sc.missTimer)
		const key = `${np.artist}\u0001${np.title}`
		if (sc.auto && sc.auto.key === key) return
		const track: Track = {
			key,
			url: '',
			searchUrl: searchLink(np.artist, np.title),
			title: np.title,
			artist: np.artist,
			artistUrl: '',
			album: np.album || '',
			artwork: np.artwork || '',
			duration: 0,
			startedAt: Date.now(),
		}
		sc.auto = track
		await hooks.refresh()
		enrich(track)
	} catch (error) {
		setStatus({
			state: 'error',
			text: String(
				(error as { message?: unknown } | undefined)?.message || error,
			),
		})
	} finally {
		sc.polling = false
		notifyListeners()
	}
}

/**
 * Starts, changes or stops the regular check of Last.fm, from the settings. When automatic mode is off, the automatic
 * track is dropped and the status falls back to the chosen link.
 */
export function restartPolling(): void {
	clearInterval(sc.pollTimer)
	sc.pollTimer = undefined
	const settings = read()
	const s = settings.soundcloud
	if (!state.active || !soundCloudOn(settings) || !s.autoEnabled) {
		if (sc.auto) {
			sc.auto = null
			if (state.active) hooks.refresh()
		}
		return
	}
	const seconds = Math.max(
		MIN_POLL_SECONDS,
		Number.parseInt(String(s.pollSeconds), 10) || 10,
	)
	sc.pollTimer = setInterval(poll, seconds * 1000)
	poll()
}

lookup.ts:
import { decode, isoDuration, meta } from './format'
import type { Track } from './types'

/**
 * Reads a track or playlist link.
 *
 * The page gives the real link (short links redirect) and the length; SoundCloud's public oEmbed gives the title, artist and
 * artwork. Either one alone is enough to show the track.
 *
 * @param link A SoundCloud link.
 * @returns The track, without a start time.
 * @throws If neither the page nor oEmbed gave a title (the track may be private).
 */
export async function lookup(link: string): Promise<Omit<Track, 'startedAt'>> {
	let html = ''
	let canonical = link
	try {
		const page = await fetch(link, { headers: { Accept: 'text/html' } })
		if (page.ok) {
			html = await page.text()
			if (page.url && /(^|\.)soundcloud\.com\//i.test(page.url))
				canonical = page.url.split('?')[0]
			const c = /<link rel="canonical" href="([^"]+)"/i.exec(html)
			if (c) canonical = decode(c[1])
		}
	} catch {
		// The page is optional: oEmbed below may still know the track.
	}

	let data:
		| {
				author_name?: string
				title?: string
				author_url?: string
				thumbnail_url?: string
		  }
		| undefined
	try {
		const res = await fetch(
			`https://soundcloud.com/oembed?format=json&url=${encodeURIComponent(canonical)}`,
		)
		if (res.ok) data = await res.json()
	} catch {
		// The page above may be enough.
	}

	const artist = data?.author_name || ''
	let title = data?.title ? String(data.title) : decode(meta(html, 'og:title'))
	if (artist && title.slice(-(artist.length + 4)) === ` by ${artist}`)
		title = title.slice(0, -(artist.length + 4))
	if (!title)
		throw new Error('Could not read this SoundCloud link. Is the track public?')

	const kind = /\/sets\//.test(canonical) ? 'playlist' : 'track'
	let duration = 0
	if (kind === 'track') {
		const iso = /itemprop="duration"[^>]*content="([^"]+)"/i.exec(html)
		const full = /"full_duration":(\d+)/.exec(html)
		duration = full ? Number(full[1]) : iso ? isoDuration(iso[1]) : 0
	}
	return {
		url: canonical,
		kind,
		title,
		artist,
		artistUrl: data?.author_url || '',
		artwork: data?.thumbnail_url || meta(html, 'og:image'),
		duration,
	}
}

present.ts:
import { Stores } from '@valenced/discord/flux'
import { dispatchActivity } from './activity'
import { FALLBACK_COVER, MAX_BUTTON_LABEL, RICH_VARS } from './constants'
import { artworkAsset } from './images'
import { effectiveAppId } from './profiles'
import { sc, tuning } from './scstate'
import type {
	Activity,
	Profile,
	RichPresenceSettings,
	Runtime,
	SoundCloudSettings,
	Standing,
	Track,
} from './types'

/** Whether a text is a web link. */
const isLink = (value: string | undefined): value is string =>
	!!value && /^https?:\/\//i.test(value)

/** What this part shares with the custom profiles: the variables `{sc_title}` and friends, and the timer for "From the SoundCloud track". */
const shared = globalThis as unknown as {
	eskimoVars?: Record<string, string>
	eskimoTimestamps?: { start: number; end?: number }
}

/** The track to show: what Last.fm says is playing, else the link you chose. */
export function effective(settings: SoundCloudSettings): Track | null {
	return settings.autoEnabled && sc.auto ? sc.auto : settings.current
}

/** The cover to show: the real one, else the plugin's default cover, else none. */
export function coverOf(settings: SoundCloudSettings, track: Track): string {
	return track.artwork || (settings.fallbackCover ? FALLBACK_COVER : '')
}

/** When the track ends (milliseconds), if the timer is the progress bar and the length is known. Otherwise 0. */
export function progressEnd(
	settings: SoundCloudSettings,
	track: Track,
): number {
	return settings.timerMode === 'progress' && track.duration > 0
		? track.startedAt + track.duration
		: 0
}

/** The button: its label (up to 32 characters) and where it goes. A track without a link opens a search for the song. */
export function buttonOf(
	settings: SoundCloudSettings,
	track: Track,
): { label: string; url: string } {
	const label = track.url
		? String(settings.buttonLabel || '').trim() || 'Listen on SoundCloud'
		: 'Find on SoundCloud'
	return {
		label: label.slice(0, MAX_BUTTON_LABEL),
		url: track.url || track.searchUrl || '',
	}
}

/**
 * True while another app, such as Spotify, is already showing a "Listening to" card. The presences of this plugin (each has
 * its own application id) do not count.
 */
export function otherListening(settings: RichPresenceSettings): boolean {
	try {
		const store = (
			Stores as unknown as {
				LocalActivityStore?: {
					getActivities?: () => Array<{
						type?: number
						name?: string
						application_id?: unknown
					}>
				}
			}
		).LocalActivityStore
		const list = store?.getActivities?.() || []
		const own = new Set(settings.profiles.map(effectiveAppId))
		return list.some(a => {
			const id = String(a?.application_id || '')
			return (
				a &&
				a.type === 2 &&
				a.name !== 'SoundCloud' &&
				id !== '0' &&
				!own.has(id)
			)
		})
	} catch {
		return false
	}
}

/** Says why the SoundCloud profile has nothing to show right now, or nothing if it has a track to show. */
export function soundCloudProblem(
	settings: RichPresenceSettings,
	now = Date.now(),
): Standing | undefined {
	const s = settings.soundcloud
	const track = effective(s)
	if (!track) return 'waiting for a track'
	if (s.hideWithSpotify && otherListening(settings)) return 'hidden by spotify'
	const end = progressEnd(s, track)
	if (s.clearAtEnd && end && now >= end) return 'track finished'
	return undefined
}

/**
 * Builds the activity Discord expects from a track.
 *
 * "Listening to" shows the app name, the artist or the title, as the settings say (the artist only if there is one). The
 * timer is the progress bar, the time elapsed, or none. The cover and the optional small icon are hosted through Discord.
 */
export async function buildSoundCloudActivity(
	p: Profile,
	settings: SoundCloudSettings,
	track: Track,
): Promise<Activity> {
	const activity: Activity = {
		application_id: effectiveAppId(p),
		name: 'SoundCloud',
		type: 2,
		flags: 1,
		details: track.title.slice(0, 128),
	}
	const hasArtist = settings.showArtist && !!track.artist
	if (hasArtist) activity.state = track.artist.slice(0, 128)
	if (isLink(track.url)) activity.details_url = track.url
	if (hasArtist && isLink(track.artistUrl)) activity.state_url = track.artistUrl
	// 0 = the app name, 1 = the state line, 2 = the details line. Fall back to the name when the line is missing.
	let display = Number(settings.statusText) || 0
	if (display === 1 && !hasArtist) display = 0
	activity.status_display_type = display

	if (settings.timerMode === 'progress') {
		const end = progressEnd(settings, track)
		activity.timestamps = end
			? { start: track.startedAt, end }
			: { start: track.startedAt }
	} else if (settings.timerMode === 'elapsed') {
		activity.timestamps = { start: track.startedAt }
	}

	const cover = settings.showArtwork ? coverOf(settings, track) : ''
	if (cover) {
		const image = await artworkAsset(cover)
		if (image) {
			// The hover text is the album when Last.fm knows it, else the title.
			activity.assets = {
				large_image: image,
				large_text: (track.album || track.title).slice(0, 128),
			}
			if (isLink(track.url)) activity.assets.large_url = track.url
		}
	}
	// An optional small icon, such as a SoundCloud logo you pick, in the corner of the cover.
	const icon = String(settings.smallIcon || '').trim()
	if (activity.assets && isLink(icon)) {
		const smallImage = await artworkAsset(icon)
		if (smallImage) {
			activity.assets.small_image = smallImage
			activity.assets.small_text = 'SoundCloud'
		}
	}
	if (settings.showButton) {
		const button = buttonOf(settings, track)
		if (isLink(button.url)) {
			activity.buttons = [button.label]
			activity.metadata = { button_urls: [button.url] }
		}
	}
	return activity
}

/**
 * Sends the update waiting to go, if Discord's allowance (4 per 20 seconds) has room. If not, a timer sends it when the
 * oldest send has aged out; only the newest update waits.
 */
function flushSend(): void {
	if (!sc.pendingSend) return
	const now = Date.now()
	sc.sentTimes = sc.sentTimes.filter(t => now - t < tuning.rateWindow)
	if (sc.sentTimes.length >= tuning.rateMax) {
		const wait = sc.sentTimes[0] + tuning.rateWindow - now + 50
		if (!sc.sendTimer) {
			sc.sendTimer = setTimeout(() => {
				sc.sendTimer = undefined
				flushSend()
			}, wait)
		}
		return
	}
	const next = sc.pendingSend
	sc.pendingSend = undefined
	sc.lastSentJson = next.json
	sc.sentTimes.push(now)
	dispatchActivity(next.activity, next.rt)
}

/**
 * Sends the SoundCloud presence, unless it is identical to the last one, and never faster than Discord allows (4 per 20 s).
 * Only an update that follows a live one can be a repeat: after the presence was taken away, the same one is sent again.
 */
export function sendSoundCloud(activity: Activity | null, rt: Runtime): void {
	const json = JSON.stringify(activity == null ? null : activity)
	if (!sc.pendingSend && rt.live && json === sc.lastSentJson) return
	sc.pendingSend = { activity, json, rt }
	flushSend()
}

/** Drops an update that is still waiting for its turn and forgets the last one, for when the presence is taken away. */
export function dropPendingSend(): void {
	clearTimeout(sc.sendTimer)
	sc.sendTimer = undefined
	sc.pendingSend = undefined
	sc.lastSentJson = ''
}

/** Hands the track to the custom profiles: `{sc_title}`, `{sc_artist}`, `{sc_url}`, `{sc_art}`, `{sc_button}` and the timer's start and end. */
export function pushVars(settings: SoundCloudSettings, track: Track): void {
	sc.varsPushed = true
	const end = progressEnd(settings, track)
	const button = buttonOf(settings, track)
	shared.eskimoVars = Object.assign(shared.eskimoVars || {}, {
		sc_title: track.title,
		sc_artist: settings.showArtist ? track.artist : '',
		sc_url: button.url,
		sc_art: settings.showArtwork ? coverOf(settings, track) : '',
		sc_button: button.label,
	})
	shared.eskimoTimestamps =
		settings.timerMode === 'none'
			? undefined
			: end
				? { start: track.startedAt, end }
				: { start: track.startedAt }
}

/** Empties the variables, so a custom profile's "show only when" hides it while nothing plays. */
export function clearVars(): boolean {
	const vars = shared.eskimoVars
	// Only what this plugin put there is emptied; variables another plugin supplies are left alone.
	if (!sc.varsPushed || !vars || !vars.sc_title) return false
	sc.varsPushed = false
	for (const key of RICH_VARS) vars[key] = ''
	shared.eskimoTimestamps = undefined
	return true
}

